# Approval records must reach quorum before repository publication is claimed.
reviews_path = Path("apps/api/src/routes/reviews.ts")
reviews_text = reviews_path.read_text(encoding="utf-8")
approve_start = reviews_text.find('      if (decision === "APPROVE") {\n')
if approve_start < 0:
    raise SystemExit("approve block missing")
store_anchor = '        const store = new GitKnowledgeStore(repositoryPath());\n'
store_pos = reviews_text.find(store_anchor, approve_start)
if store_pos < 0:
    raise SystemExit("approve store anchor missing")
approval_prefix = '''        if (!actor) return reply.code(401).send({ code: "AUTHENTICATION_REQUIRED" });\n        let approval: Awaited<ReturnType<typeof recordReviewApproval>>;\n        try {\n          approval = await recordReviewApproval(db, {\n            reviewId: request.params.id,\n            actor,\n            reason: request.body.reason ?? "",\n          });\n        } catch (error) {\n          const code = error instanceof Error ? error.message : String(error);\n          const status = reviewPolicyDecisionHttpStatus(code);\n          if (status) return reply.code(status).send({ code });\n          throw error;\n        }\n        await audit(\n          db,\n          request,\n          "review.approval_recorded",\n          "review",\n          request.params.id,\n          {\n            vaultId: String(review.vault_id),\n            reviewerRole: approval.reviewerRole,\n            approvalCount: approval.approvalCount,\n            minimumApprovals: approval.minimumApprovals,\n            duplicate: approval.duplicate,\n            reviewRound: approval.reviewRound,\n          },\n          String(review.space_id),\n        );\n        if (!approval.quorumReached) {\n          return {\n            id: request.params.id,\n            status: "PENDING",\n            approvalProgress: {\n              reviewRound: approval.reviewRound,\n              count: approval.approvalCount,\n              minimumApprovals: approval.minimumApprovals,\n              remainingApprovals:\n                approval.minimumApprovals - approval.approvalCount,\n              duplicate: approval.duplicate,\n            },\n          };\n        }\n'''
reviews_text = reviews_text[:store_pos] + approval_prefix + reviews_text[store_pos:]
claim_start = reviews_text.find('          const claimed = await db.pool.query(\n', approve_start)
claim_end = reviews_text.find('          await renewPublicationLock', claim_start)
if claim_start < 0 or claim_end < 0:
    raise SystemExit("legacy publication claim anchor missing")
claim_replacement = '''          let claimedReview: Record<string, unknown>;\n          try {\n            claimedReview = await claimReviewForPublication(db, {\n              reviewId: request.params.id,\n              expectedHeadCommit: approval.headCommit,\n              expectedPolicyFingerprint: approval.policyFingerprint,\n              expectedReviewRound: approval.reviewRound,\n              actorId: actor.id,\n              reason: request.body.reason ?? "",\n            });\n          } catch (error) {\n            const code = error instanceof Error ? error.message : String(error);\n            const status = reviewPolicyDecisionHttpStatus(code);\n            if (status) return reply.code(status).send({ code });\n            throw error;\n          }\n'''
reviews_text = reviews_text[:claim_start] + claim_replacement + reviews_text[claim_end:]
reviews_text = reviews_text.replace(
    'claimed.rows[0] as Record<string, unknown>',
    'claimedReview',
    1,
)
reviews_text = reviews_text.replace(
    '            mergedCommit: revision,\n            indexing: "PENDING",\n',
    '''            mergedCommit: revision,\n            approvalProgress: {\n              reviewRound: approval.reviewRound,\n              count: approval.approvalCount,\n              minimumApprovals: approval.minimumApprovals,\n              remainingApprovals: 0,\n            },\n            indexing: "PENDING",\n''',
    1,
)
reviews_path.write_text(reviews_text, encoding="utf-8")

# Human request-changes opens a new approval round without deleting audit history.
replace_once(
    "apps/api/src/routes/reviews.ts",
    '''        update reviews set status=$2,decision_by=$3,decision_at=now(),\n               decision_reason=$4,updated_at=now()\n''',
    '''        update reviews set status=$2,decision_by=$3,decision_at=now(),\n               decision_reason=$4,\n               review_round=case when $2='CHANGES_REQUESTED' then review_round+1 else review_round end,\n               updated_at=now()\n''',
)

# Migration 030: immutable approval facts keyed by round/head/policy/reviewer.
write(
    "db/migrations/030_review_policy_approvals.sql",
    '''alter table reviews\n  add column review_round integer not null default 1\n  check (review_round > 0);\n\ncreate table review_approvals (\n  id uuid primary key default gen_random_uuid(),\n  review_id uuid not null references reviews(id) on delete cascade,\n  review_round integer not null check (review_round > 0),\n  head_commit text not null check (length(btrim(head_commit)) > 0),\n  policy_fingerprint text not null\n    check (policy_fingerprint ~ '^[a-f0-9]{64}$'),\n  profile_source text not null\n    check (profile_source in ('DURABLE_REVISION', 'V03_DEFAULT')),\n  profile_revision_id uuid references knowledge_profile_revisions(id),\n  profile_hash text not null check (profile_hash ~ '^[a-f0-9]{64}$'),\n  reviewer_id uuid not null references users(id),\n  reviewer_role text not null check (length(btrim(reviewer_role)) > 0),\n  reason text not null check (length(btrim(reason)) > 0),\n  created_at timestamptz not null default now(),\n  constraint review_approvals_profile_source_shape check (\n    (profile_source='V03_DEFAULT' and profile_revision_id is null) or\n    (profile_source='DURABLE_REVISION' and profile_revision_id is not null)\n  ),\n  unique (\n    review_id,review_round,head_commit,policy_fingerprint,reviewer_id\n  )\n);\n\ncreate index review_approvals_quorum_idx\n  on review_approvals(review_id,review_round,head_commit,policy_fingerprint,created_at);\ncreate index review_approvals_reviewer_idx\n  on review_approvals(reviewer_id,created_at desc);\n\ncomment on table review_approvals is\n  'Append-only approval facts. Quorum is counted only for the exact review round, draft head and effective KnowledgeProfile review-policy fingerprint.';\n''',
)

# Integration proof: role narrowing, two distinct reviewers, duplicate dedupe,
# stale profile fail-closed, and durable-profile kind enforcement.
write(
    "apps/api/test/review-policy.integration.test.ts",
    '''import { createHash, randomUUID } from "node:crypto";\nimport { mkdtemp, rm } from "node:fs/promises";\nimport { tmpdir } from "node:os";\nimport path from "node:path";\nimport { afterAll, beforeAll, describe, expect, it } from "vitest";\nimport type { FastifyInstance } from "fastify";\nimport {\n  KnowledgeProfileV1,\n  NEUTRAL_KNOWLEDGE_PROFILE_V1,\n  canonicalKnowledgeProfileJson,\n} from "@akp/contracts/knowledge-profile";\nimport { Postgres, grantVaultMembership } from "@akp/postgres";\n\nconst spaceId = "00000000-0000-0000-0000-000000000003";\nconst adminId = "00000000-0000-0000-0000-000000000002";\nconst reviewerOneId = randomUUID();\nconst reviewerTwoId = randomUUID();\nconst vaultId = randomUUID();\nconst adminToken = `review-policy-admin-${randomUUID()}`;\nconst reviewerOneToken = `review-policy-one-${randomUUID()}`;\nconst reviewerTwoToken = `review-policy-two-${randomUUID()}`;\nconst tokenHash = (token: string) =>\n  createHash("sha256").update(token).digest("hex");\nconst adminHeaders = { authorization: `Bearer ${adminToken}` };\nconst reviewerOneHeaders = { authorization: `Bearer ${reviewerOneToken}` };\nconst reviewerTwoHeaders = { authorization: `Bearer ${reviewerTwoToken}` };\n\nlet app: FastifyInstance;\nlet db: Postgres;\nlet fixtureRoot: string;\nlet activeProfileRevisionId: string;\nconst reviewIds = new Set<string>();\nconst previousManagedRepository = process.env.AKP_MANAGED_REPO;\n\nfunction profile(version: string) {\n  return KnowledgeProfileV1.parse({\n    ...NEUTRAL_KNOWLEDGE_PROFILE_V1,\n    version,\n    reviewPolicies: {\n      ...NEUTRAL_KNOWLEDGE_PROFILE_V1.reviewPolicies,\n      "neutral-review": {\n        required: true,\n        minimumApprovals: 2,\n        allowedRoles: ["REVIEWER"],\n      },\n    },\n  });\n}\n\nasync function activateProfile(version: string): Promise<string> {\n  const candidate = profile(version);\n  const canonical = canonicalKnowledgeProfileJson(candidate);\n  const hash = createHash("sha256").update(canonical).digest("hex");\n  const revisionId = randomUUID();\n  const client = await db.pool.connect();\n  try {\n    await client.query("begin");\n    await client.query(\n      `update knowledge_profile_revisions\n          set status='SUPERSEDED',superseded_at=now(),updated_at=now()\n        where vault_id=$1 and status='ACTIVE'`,\n      [vaultId],\n    );\n    await client.query(\n      `\n      insert into knowledge_profile_revisions(\n        id,space_id,vault_id,profile_id,version,profile_hash,canonical_profile,\n        status,compatibility_class,created_by,validation_report,validated_at,activated_at\n      ) values($1,$2,$3,$4,$5,$6,$7,'ACTIVE','NON_BREAKING',$8,'{}'::jsonb,now(),now())\n      `,\n      [\n        revisionId,\n        spaceId,\n        vaultId,\n        candidate.profileId,\n        version,\n        hash,\n        canonical,\n        adminId,\n      ],\n    );\n    await client.query(\n      "update vaults set active_knowledge_profile_revision_id=$2 where id=$1 and space_id=$3",\n      [vaultId, revisionId, spaceId],\n    );\n    await client.query("commit");\n  } catch (error) {\n    await client.query("rollback");\n    throw error;\n  } finally {\n    client.release();\n  }\n  activeProfileRevisionId = revisionId;\n  return revisionId;\n}\n\nfunction documentContent(type = "note"): string {\n  return `---\ntype: ${type}\ntitle: Review policy integration fixture\nstatus: DRAFT\nknowledge_layer: notes\n---\n\n# Review policy integration fixture\n\nThis deliberately substantive document proves durable profile-bound review\npolicy enforcement with multiple distinct human reviewers and a pinned profile\nrevision. The body is intentionally longer than the validation thin-content\nthreshold so the integration path exercises review governance rather than a\ncontent warning.\n`;\n}\n\nasync function propose(type = "note") {\n  const response = await app.inject({\n    method: "POST",\n    url: "/v1/proposals",\n    headers: adminHeaders,\n    payload: {\n      spaceId,\n      vaultId,\n      summary: `review policy ${type}`,\n      changes: [\n        {\n          path: `knowledge/${type}/${randomUUID()}.md`,\n          content: documentContent(type),\n        },\n      ],\n    },\n  });\n  if (response.statusCode === 201) {\n    reviewIds.add((response.json() as { reviewId: string }).reviewId);\n  }\n  return response;\n}\n\nasync function approve(reviewId: string, headers: Record<string, string>) {\n  return app.inject({\n    method: "POST",\n    url: `/v1/reviews/${reviewId}/decision`,\n    headers,\n    payload: { decision: "APPROVE", reason: "profile policy approval" },\n  });\n}\n\nbeforeAll(async () => {\n  if (!process.env.DATABASE_URL) {\n    throw new Error("DATABASE_URL is required for integration tests.");\n  }\n  process.env.NODE_ENV = "test";\n  fixtureRoot = await mkdtemp(path.join(tmpdir(), "akp-review-policy-"));\n  process.env.AKP_MANAGED_REPO = path.join(fixtureRoot, "managed-repository");\n  db = new Postgres(process.env.DATABASE_URL);\n  await db.pool.query(\n    `\n    insert into vaults(\n      id,space_id,canonical_path,name,read_only,current_revision,vault_key,\n      local_path,visibility,enabled\n    ) values($1,$2,$3,$4,true,'fixture:initial',$5,$3,'PRIVATE',true)\n    `,\n    [\n      vaultId,\n      spaceId,\n      path.join(fixtureRoot, "canonical-vault"),\n      "Review policy integration vault",\n      `review-policy-${vaultId.slice(0, 8)}`,\n    ],\n  );\n  await db.pool.query(\n    `insert into users(id,email,display_name) values\n      ($1,$2,'Review Policy One'),($3,$4,'Review Policy Two')`,\n    [\n      reviewerOneId,\n      `${reviewerOneId}@example.test`,\n      reviewerTwoId,\n      `${reviewerTwoId}@example.test`,\n    ],\n  );\n  await db.pool.query(\n    `insert into memberships(user_id,space_id,role,path_prefix) values\n      ($1,$3,'REVIEWER',null),($2,$3,'REVIEWER',null)`,\n    [reviewerOneId, reviewerTwoId, spaceId],\n  );\n  await grantVaultMembership(db, {\n    userId: adminId,\n    vaultId,\n    role: "ADMIN",\n    pathPrefix: null,\n    permissions: [\n      "knowledge:read",\n      "source:read",\n      "knowledge:propose",\n      "knowledge:review",\n      "admin",\n    ],\n  });\n  for (const reviewerId of [reviewerOneId, reviewerTwoId]) {\n    await grantVaultMembership(db, {\n      userId: reviewerId,\n      vaultId,\n      role: "REVIEWER",\n      pathPrefix: null,\n      permissions: ["knowledge:read", "source:read", "knowledge:review"],\n    });\n  }\n  const tokenRows = [\n    {\n      userId: adminId,\n      token: adminToken,\n      label: "review policy admin",\n      permissions: [\n        "knowledge:read",\n        "source:read",\n        "knowledge:propose",\n        "knowledge:review",\n        "admin",\n      ],\n    },\n    {\n      userId: reviewerOneId,\n      token: reviewerOneToken,\n      label: "review policy one",\n      permissions: ["knowledge:read", "source:read", "knowledge:review"],\n    },\n    {\n      userId: reviewerTwoId,\n      token: reviewerTwoToken,\n      label: "review policy two",\n      permissions: ["knowledge:read", "source:read", "knowledge:review"],\n    },\n  ];\n  for (const tokenRow of tokenRows) {\n    await db.pool.query(\n      `insert into api_tokens(user_id,token_hash,label,scopes)\n       values($1,$2,$3,$4::jsonb)`,\n      [\n        tokenRow.userId,\n        tokenHash(tokenRow.token),\n        tokenRow.label,\n        JSON.stringify({\n          spaces: [\n            { spaceId, pathPrefix: null, permissions: tokenRow.permissions },\n          ],\n        }),\n      ],\n    );\n  }\n  await activateProfile("1.0.1-review-policy");\n  const module = await import("../src/server.js");\n  app = module.buildServer();\n});\n\nafterAll(async () => {\n  if (app) await app.close();\n  if (db) {\n    const ids = [...reviewIds];\n    if (ids.length) {\n      await db.pool.query(\n        "delete from audit_events where resource_type='review' and resource_id=any($1::text[])",\n        [ids],\n      );\n      await db.pool.query(\n        "delete from error_book where metadata->>'reviewId'=any($1::text[])",\n        [ids],\n      );\n      await db.pool.query("delete from reviews where id=any($1::uuid[])", [ids]);\n    }\n    await db.pool.query(\n      "delete from api_tokens where token_hash=any($1::text[])",\n      [[tokenHash(adminToken), tokenHash(reviewerOneToken), tokenHash(reviewerTwoToken)]],\n    );\n    await db.close();\n  }\n  if (fixtureRoot) await rm(fixtureRoot, { recursive: true, force: true });\n  if (previousManagedRepository === undefined) {\n    delete process.env.AKP_MANAGED_REPO;\n  } else {\n    process.env.AKP_MANAGED_REPO = previousManagedRepository;\n  }\n});\n\ndescribe("KnowledgeProfile review policy integration", () => {\n  it("requires allowed roles and two distinct reviewers before publication", async () => {\n    const proposed = await propose("note");\n    expect(proposed.statusCode).toBe(201);\n    const reviewId = (proposed.json() as { reviewId: string }).reviewId;\n    const persisted = await db.pool.query<{ impact_manifest: Record<string, unknown> }>(\n      "select impact_manifest from reviews where id=$1",\n      [reviewId],\n    );\n    expect(persisted.rows[0]?.impact_manifest).toMatchObject({\n      reviewKinds: ["note"],\n      reviewPolicyPinned: true,\n      reviewPolicy: {\n        minimumApprovals: 2,\n        allowedRoles: ["REVIEWER"],\n        profileRevisionId: activeProfileRevisionId,\n      },\n    });\n\n    const adminApproval = await approve(reviewId, adminHeaders);\n    expect(adminApproval.statusCode).toBe(403);\n    expect(adminApproval.json()).toMatchObject({ code: "REVIEW_ROLE_NOT_ALLOWED" });\n\n    const first = await approve(reviewId, reviewerOneHeaders);\n    expect(first.statusCode).toBe(200);\n    expect(first.json()).toMatchObject({\n      status: "PENDING",\n      approvalProgress: { count: 1, minimumApprovals: 2 },\n    });\n    const duplicate = await approve(reviewId, reviewerOneHeaders);\n    expect(duplicate.statusCode).toBe(200);\n    expect(duplicate.json()).toMatchObject({\n      status: "PENDING",\n      approvalProgress: { count: 1, minimumApprovals: 2, duplicate: true },\n    });\n    const beforeFinal = await db.pool.query<{ status: string }>(\n      "select status from reviews where id=$1",\n      [reviewId],\n    );\n    expect(beforeFinal.rows[0]?.status).toBe("PENDING");\n\n    const second = await approve(reviewId, reviewerTwoHeaders);\n    expect(second.statusCode).toBe(200);\n    expect(second.json()).toMatchObject({\n      status: "APPROVED",\n      approvalProgress: { count: 2, minimumApprovals: 2 },\n    });\n    const approvals = await db.pool.query<{ count: number }>(\n      "select count(distinct reviewer_id)::int count from review_approvals where review_id=$1",\n      [reviewId],\n    );\n    expect(approvals.rows[0]?.count).toBe(2);\n  });\n\n  it("fails closed when the active profile revision changes after review creation", async () => {\n    const proposed = await propose("note");\n    expect(proposed.statusCode).toBe(201);\n    const reviewId = (proposed.json() as { reviewId: string }).reviewId;\n    await activateProfile("1.0.2-review-policy");\n\n    const stale = await approve(reviewId, reviewerOneHeaders);\n    expect(stale.statusCode).toBe(409);\n    expect(stale.json()).toMatchObject({ code: "REVIEW_PROFILE_STALE" });\n    const approvals = await db.pool.query<{ count: number }>(\n      "select count(*)::int count from review_approvals where review_id=$1",\n      [reviewId],\n    );\n    expect(approvals.rows[0]?.count).toBe(0);\n  });\n\n  it("rejects a direct proposal kind not declared by the durable profile", async () => {\n    const response = await propose("rule");\n    expect(response.statusCode).toBe(422);\n    expect(response.json()).toMatchObject({\n      code: "KNOWLEDGE_PROFILE_KIND_NOT_ALLOWED",\n      kind: "rule",\n    });\n  });\n});\n''',
)

